/* Node detail page (generated by tools/build-knowledge-pages.mjs). The page is complete without this script;
   it renders formulas, shows the explainer in place and opens the 刷题 dialog. */
import {renderExplainer} from '/assets/explain/explain.js?v=2';

if (window.PracticeMath) {
  for (const element of document.querySelectorAll('main [data-math-text]')) window.PracticeMath.render(element, element.textContent);
}

const box = document.querySelector('[data-explainer]');
if (box) {
  renderExplainer(box, box.dataset.explainer).catch(() => {
    box.innerHTML = '<p class="kn-none">图解暂时打不开，请刷新后重试。</p>';
  });
}

const source = document.getElementById('kn-drill-data');
if (source) {
  const data = JSON.parse(source.textContent);
  let drill = null;
  for (const button of document.querySelectorAll('[data-drill-open]')) {
    button.hidden = false;
    button.addEventListener('click', () => {
      drill ||= import('/knowledge/drill.js?v=2');
      drill.then(module => module.openDrill(data)).catch(() => {
        drill = null;
        button.textContent = '刷题暂时打不开，请刷新后重试';
      });
    });
  }
}

if (source) {
  const {states, block, watch, evidence} = await import('/knowledge/personal.js?v=1');
  const node=JSON.parse(source.textContent).node;
  const status=document.createElement('div'), records=document.createElement('div');
  document.querySelector('.kn-hero').after(status);source.before(records);let ticket=0;
  const refresh=async()=>{
    const current=++ticket,user=window.SiteAuth?.user;
    status.replaceChildren();records.replaceChildren();if(!user)return;
    try{const map=await states(user);if(current!==ticket)return;status.innerHTML=block(map.get(node));await evidence(node,records,user);}
    catch{if(current===ticket)status.textContent='学习记录暂时无法读取，请稍后刷新。';}
  };
  await window.SiteAuth?.ready;refresh();watch(refresh);
  window.addEventListener('site-auth-change',refresh);
}
